// 방울이 화면에서 공유하는 디자인 토큰과 UI 컴포넌트
import React from 'react'

const BGC = {
  sky: '#4FB1F0', skyDeep: '#2E86C9', skyPale: '#EAF5FD', bg: '#F2FAFF',
  yellow: '#FFD23F', yellowDeep: '#F5A623', orange: '#F5894F',
  ink: '#214459', sub: '#7395AB', line: '#DDEEFA',
  green: '#3FAE7C', red: '#D9544A',
};

function MIcon({ name, size = 22, color = 'currentColor', fill = 1, style }) {
  return (
    <span className="msym" aria-hidden="true" style={{
      fontSize: size, color, lineHeight: 1,
      fontVariationSettings: `'FILL' ${fill}, 'wght' 500`, ...style,
    }}>{name}</span>
  );
}

function Card({ children, style, pad = 18 }) {
  return <div className="bg-card" style={{ padding: pad, ...style }}>{children}</div>;
}

function CoinChip({ n, small = false }) {
  return (
    <div style={{
      display: 'inline-flex', alignItems: 'center', gap: 6,
      background: '#FFF6D8', border: '1.5px solid #F3DF9B', borderRadius: 99,
      padding: small ? '3px 10px 3px 5px' : '5px 13px 5px 6px',
    }}>
      <img src="data:image/png;base64," alt="나무코인" style={{ width: small ? 18 : 22, height: small ? 18 : 22 }}></img>
      <span className="jua" style={{ fontSize: small ? 14 : 16, color: '#8A6A14' }}>{n.toLocaleString()}</span>
    </div>
  );
}

function PrimaryBtn({ children, onClick, icon, bg = BGC.sky, style, disabled }) {
  return (
    <button className="press" onClick={onClick} disabled={disabled} style={{
      display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
      width: '100%', minHeight: 54, border: 'none', borderRadius: 18, cursor: 'pointer',
      background: disabled ? '#C7DDEE' : bg, color: '#fff',
      fontFamily: 'Jua', fontSize: 18, letterSpacing: 0.5,
      boxShadow: disabled ? 'none' : '0 4px 0 rgba(33,68,89,0.18)', ...style,
    }}>
      {icon && <MIcon name={icon} size={22} color="#fff"></MIcon>}
      {children}
    </button>
  );
}

function GhostBtn({ children, onClick, icon, style }) {
  return (
    <button className="press" onClick={onClick} style={{
      display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
      width: '100%', minHeight: 54, borderRadius: 18, cursor: 'pointer',
      background: '#fff', border: `2px solid ${BGC.line}`, color: BGC.ink,
      fontFamily: 'Jua', fontSize: 17, ...style,
    }}>
      {icon && <MIcon name={icon} size={20} color={BGC.sub}></MIcon>}
      {children}
    </button>
  );
}

function SectionLabel({ icon, children, right }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 7, marginBottom: 10 }}>
      {icon && <MIcon name={icon} size={19} color={BGC.skyDeep}></MIcon>}
      <span className="jua" style={{ fontSize: 17, color: BGC.ink, flex: 1 }}>{children}</span>
      {right}
    </div>
  );
}

function WaterBar({ value, goal, height = 16 }) {
  const pct = Math.min(100, Math.round((value / goal) * 100));
  const over = value > goal;
  return (
    <div style={{ position: 'relative', height, borderRadius: 99, background: '#E2F1FC', overflow: 'hidden' }}>
      <div style={{
        position: 'absolute', top: 0, left: 0, bottom: 0, width: pct + '%', borderRadius: 99,
        background: over ? 'linear-gradient(90deg,#FFC46B,#F5894F)' : 'linear-gradient(90deg,#7BCBFF,#2E86C9)',
        transition: 'width .6s ease',
      }}></div>
    </div>
  );
}

function MoistureDots({ filled, total = 5 }) {
  return (
    <div style={{ display: 'flex', gap: 5 }}>
      {Array.from({ length: total }, (_, i) => (
        <div key={i} style={{
          width: 13, height: 13, borderRadius: '50%',
          background: i < filled ? BGC.sky : '#D5E9F8',
          border: i < filled ? '1.5px solid #2E86C9' : '1.5px solid #C3DDF1',
        }}></div>
      ))}
    </div>
  );
}

function SpeechBubble({ children, style }) {
  return (
    <div style={{
      position: 'relative', background: '#fff', borderRadius: 16, padding: '10px 16px',
      boxShadow: '0 3px 10px rgba(46,116,170,0.14)', fontSize: 13.5, color: BGC.ink,
      fontWeight: 500, textAlign: 'center', lineHeight: 1.45, ...style,
    }}>
      {children}
      <div style={{
        position: 'absolute', bottom: -5, left: '50%', width: 11, height: 11,
        background: '#fff', transform: 'translateX(-50%) rotate(45deg)',
      }}></div>
    </div>
  );
}

